INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('sweet potatoes','Sweet potatoes','4 medium','Produce','For the beef and black bean stuffed sweet potatoes.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('avocados','Avocados','2','Produce','One slightly soft for soon, one firmer for later.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('limes','Limes','3','Produce','Two for the sweet potatoes and yogurt sauce; one for satay.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('cilantro','Cilantro','1 bunch, optional','Produce','Shared topping for both recipes.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('bananas','Bananas','5–7','Produce','For breakfast or snacks.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('fresh chili','Fresh chili','1, optional','Produce','For serving with satay if you want extra heat.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('boneless skinless chicken thighs','Boneless, skinless chicken thighs','About 1¼ lb','Meat, dairy, and refrigerated','The satay recipe uses 500g, about 1.1 lb.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('plain greek yogurt','Plain Greek yogurt','2 large tubs, around 32 oz each','Meat, dairy, and refrigerated','Nonfat or 2%. Use for breakfasts and the lime sauce. Compare price per ounce.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('eggs','Eggs','1 dozen','Meat, dairy, and refrigerated','Easy protein for breakfast and rice bowls.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('cottage cheese','Cottage cheese','1 tub, optional','Meat, dairy, and refrigerated','An extra protein option if you like it.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('pico de gallo','Pico de gallo','1 tub, mild or hot','Meat, dairy, and refrigerated','For sweet potatoes, eggs, and rice bowls. Substitute a jar of salsa if unavailable.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('rice','Rice','1 bag','Rice, beans, and pantry','For everyday bowls and satay. Satay uses 300g cooked rice for two bowls.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('canned black beans','Canned black beans','4 cans','Rice, beans, and pantry','Use one 15 oz can for the stuffed sweet potatoes; save the rest for rice bowls.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('rolled oats','Rolled oats','1 bag or container','Rice, beans, and pantry','For oatmeal or overnight oats with yogurt.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('coconut milk','Coconut milk','1 can','Rice, beans, and pantry','Satay needs 50ml for the marinade plus 1 tbsp for the sauce.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('powdered peanut butter','Powdered peanut butter','1 container; recipe uses 40g','Rice, beans, and pantry','TJ’s availability is unconfirmed; another store may be needed. Regular peanut butter also works, thinned with warm water, but changes the macros.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('thai red curry paste','Thai red curry paste','1 small jar; recipe uses 2 tsp','Rice, beans, and pantry','TJ’s availability is unconfirmed; another store may be needed. Curry simmer sauce is not the same ingredient.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('curry powder','Curry powder','1 jar if needed; recipe uses 1 tbsp','Rice, beans, and pantry','');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('honey','Honey','If needed; recipe uses 1 tsp','Rice, beans, and pantry','');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('soy sauce','Soy sauce','If needed; recipe uses 1 tsp','Rice, beans, and pantry','Regular soy sauce is a workable substitute with a different flavor. Dark soy availability at TJ’s is unconfirmed.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('roasted peanuts','Roasted peanuts','1 small bag, optional','Rice, beans, and pantry','Crush a teaspoon for the satay sauce or garnish.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('taco seasoning','Taco seasoning','Only if needed','Rice, beans, and pantry','Use the cumin, chili powder, and garlic powder you already have instead.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('frozen berries','Frozen berries','1 bag','Freezer','For Greek yogurt and oats.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('plain frozen broccoli or mixed vegetables','Plain frozen broccoli or mixed vegetables','2 bags','Freezer','Sides for rice bowls and orange chicken.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('frozen shelled edamame','Frozen shelled edamame','1 bag','Freezer','Protein and fiber for bowls or snacks.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('chicken burrito bowls','Chicken Burrito Bowls','2','Freezer','Microwave backup meals. Check the current package for nutrition and cooking directions.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('teriyaki chicken bowls','Teriyaki Chicken Bowls','1–2','Freezer','An easy chicken, rice, and vegetable meal.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('mandarin orange chicken','Mandarin Orange Chicken','1 bag','Freezer','Pair with your rice and frozen broccoli.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('marula oil cream cleanser','Marula Oil Cream Cleanser','1 tube','Skincare','Listed at $6.99 for 5 oz. Low-lather cream cleanser with 1% colloidal oatmeal.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('daily facial mineral sunscreen spf 40','Daily Facial Mineral Sunscreen SPF 40','1 tube','Skincare','Budget about $13; check the shelf price. Look specifically for Mineral. May leave a white cast.');
INSERT INTO groceries (item_key,name,quantity,category,note) VALUES ('ultra hydrating gel moisturizer','Ultra Hydrating Gel Moisturizer','1 jar, optional','Skincare','Budget about $9. A lightweight option for mild dryness; a richer fragrance-free cream may suit very dry skin better. Keep an existing moisturizer if it works well.');
